from flask import Flask, Blueprint, jsonify, request

app = Flask(__name__)

users_bp = Blueprint('users', __name__)

@users_bp.route('/', methods=['GET'])
def get_users():
    return jsonify([
        {'id': 1, 'name': 'Alice'},
        {'id': 2, 'name': 'Bob'},
        {'id': 3, 'name': 'Charlie'}
    ])

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    return jsonify({'id': user_id, 'name': f'User {user_id}'})

@users_bp.route('/', methods=['POST'])
def create_user():
    data = request.get_json()
    return jsonify({'id': 4, 'name': data.get('name', 'New User')}), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    data = request.get_json()
    return jsonify({'id': user_id, 'name': data.get('name', f'User {user_id}')})

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return jsonify({'message': f'User {user_id} deleted'}), 204

app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/')
def index():
    return jsonify({'message': 'Flask App with Modular Users Component'})

if __name__ == '__main__':
    app.run(debug=True)

